"""Tests for the rlsbl commit command and autogenerated trailer support."""

import subprocess
from unittest.mock import patch, call

import pytest

from rlsbl.utils import commit_files
import rlsbl.utils


class TestAutogeneratedTrailer:
    """Tests for the autogenerated parameter in commit_files."""

    @patch("rlsbl.utils.run")
    @patch("shutil.which", return_value="/usr/bin/safegit")
    def test_autogenerated_true_appends_trailer(self, mock_which, mock_run):
        commit_files("test message", ["file.py"], autogenerated=True)
        mock_run.assert_called_once_with(
            "safegit",
            ["commit", "--yes", "--trailer", "Autogenerated: true", "-m", "test message", "--", "file.py"], cwd=None,
        )

    @patch("rlsbl.utils.run")
    @patch("shutil.which", return_value="/usr/bin/safegit")
    def test_autogenerated_false_no_trailer(self, mock_which, mock_run):
        commit_files("test message", ["file.py"], autogenerated=False)
        mock_run.assert_called_once_with(
            "safegit",
            ["commit", "--yes", "-m", "test message", "--", "file.py"], cwd=None,
        )

    @patch("rlsbl.utils.run")
    @patch("shutil.which", return_value="/usr/bin/safegit")
    def test_autogenerated_default_is_true(self, mock_which, mock_run):
        """Default call (no autogenerated kwarg) should produce a --trailer flag."""
        commit_files("test message", ["file.py"])
        mock_run.assert_called_once_with(
            "safegit",
            ["commit", "--yes", "--trailer", "Autogenerated: true", "-m", "test message", "--", "file.py"], cwd=None,
        )

    @patch("rlsbl.utils.run")
    @patch("shutil.which", return_value=None)
    def test_autogenerated_with_git_fallback(self, mock_which, mock_run):
        # Reset warning flag so we don't interfere with other tests
        rlsbl.utils._safegit_warning_shown = True
        commit_files("test message", ["file.py"], autogenerated=True)
        assert mock_run.call_count == 2
        mock_run.assert_any_call("git", ["add", "file.py"], cwd=None)
        mock_run.assert_any_call(
            "git", ["commit", "--trailer", "Autogenerated: true", "-m", "test message"], cwd=None,
        )


class TestAutogeneratedTrailerIntegration:
    """Integration test verifying git actually recognizes the trailer."""

    def test_trailer_recognized_by_git(self, mock_git_repo):
        """Verify git log can extract the Autogenerated trailer."""
        repo = mock_git_repo
        # Create a file and commit with the trailer
        test_file = repo / "generated.txt"
        test_file.write_text("generated content\n")
        subprocess.run(
            ["git", "add", "generated.txt"], cwd=str(repo), check=True
        )
        subprocess.run(
            ["git", "commit", "--trailer", "Autogenerated: true", "-m", "auto commit"],
            cwd=str(repo),
            check=True,
        )
        # Verify git can parse the trailer
        result = subprocess.run(
            ["git", "log", "-1", "--format=%(trailers:key=Autogenerated,valueonly)"],
            cwd=str(repo),
            capture_output=True,
            text=True,
            check=True,
        )
        assert result.stdout.strip() == "true"

    def test_no_trailer_when_not_autogenerated(self, mock_git_repo):
        """Verify regular commits have no Autogenerated trailer."""
        repo = mock_git_repo
        test_file = repo / "normal.txt"
        test_file.write_text("normal content\n")
        subprocess.run(
            ["git", "add", "normal.txt"], cwd=str(repo), check=True
        )
        subprocess.run(
            ["git", "commit", "-m", "normal commit"],
            cwd=str(repo),
            check=True,
        )
        result = subprocess.run(
            ["git", "log", "-1", "--format=%(trailers:key=Autogenerated,valueonly)"],
            cwd=str(repo),
            capture_output=True,
            text=True,
            check=True,
        )
        assert result.stdout.strip() == ""


class TestSafegitWarnOnce:
    """Tests for the one-time safegit fallback warning."""

    def test_warns_on_first_call(self, capsys):
        # Reset the module-level flag
        rlsbl.utils._safegit_warning_shown = False
        with patch("shutil.which", return_value=None):
            tool = rlsbl.utils.find_commit_tool()
        assert tool == "git"
        captured = capsys.readouterr()
        assert "note: safegit not found" in captured.err
        assert "concurrent commits may conflict" in captured.err

    def test_no_warning_on_second_call(self, capsys):
        # Ensure the flag is set (simulating first call already happened)
        rlsbl.utils._safegit_warning_shown = True
        with patch("shutil.which", return_value=None):
            tool = rlsbl.utils.find_commit_tool()
        assert tool == "git"
        captured = capsys.readouterr()
        assert captured.err == ""

    def test_no_warning_when_safegit_found(self, capsys):
        rlsbl.utils._safegit_warning_shown = False
        with patch("shutil.which", return_value="/usr/bin/safegit"):
            tool = rlsbl.utils.find_commit_tool()
        assert tool == "safegit"
        captured = capsys.readouterr()
        assert captured.err == ""


class TestCommitCommand:
    """Tests for the rlsbl commit command handler."""

    @patch("rlsbl.utils.run")
    @patch("shutil.which", return_value="/usr/bin/safegit")
    def test_run_cmd_calls_commit_files_with_autogenerated(
        self, mock_which, mock_run
    ):
        from rlsbl.commands.commit_cmd import run_cmd

        run_cmd("my message", ["a.txt", "b.txt"])
        mock_run.assert_called_once_with(
            "safegit",
            [
                "commit",
                "--yes",
                "--trailer",
                "Autogenerated: true",
                "-m",
                "my message",
                "--",
                "a.txt",
                "b.txt",
            ], cwd=None,
        )

    @patch(
        "rlsbl.utils.run",
        side_effect=subprocess.CalledProcessError(1, "safegit"),
    )
    @patch("shutil.which", return_value="/usr/bin/safegit")
    def test_run_cmd_exits_on_failure(self, mock_which, mock_run):
        from rlsbl.commands.commit_cmd import run_cmd

        with pytest.raises(subprocess.CalledProcessError):
            run_cmd("msg", ["file.txt"])
